insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0001', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Explore', 'easy', 'multiple_choice', 'Four figures: A small green triangle with a dot, B large green triangle, C small green pentagon, D large green pentagon. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure B"}, {"id": "B", "text": "Figure C"}, {"id": "C", "text": "Figure A"}, {"id": "D", "text": "Figure D"}]', 'C', 'A figure has a dot exactly when it has an even number of sides. Check each figure: A small green triangle with a dot breaks the rule. B large green triangle follows the rule. C small green pentagon follows the rule. D large green pentagon follows the rule. So Figure A is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-A'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0002', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Explore', 'easy', 'multiple_choice', 'Four figures: A large red hexagon, B large blue square, C small green triangle with a dot, D small green square. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure A"}, {"id": "B", "text": "Figure D"}, {"id": "C", "text": "Figure C"}, {"id": "D", "text": "Figure B"}]', 'B', 'A figure is small exactly when it is a triangle. Check each figure: A large red hexagon follows the rule. B large blue square follows the rule. C small green triangle with a dot follows the rule. D small green square breaks the rule. So Figure D is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-B'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0003', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Explore', 'easy', 'multiple_choice', 'Four figures: A small green pentagon with a dot, B large green triangle with a dot, C large red triangle, D small blue hexagon. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure D"}, {"id": "B", "text": "Figure B"}, {"id": "C", "text": "Figure C"}, {"id": "D", "text": "Figure A"}]', 'D', 'A figure is blue exactly when it has more than 4 sides. Check each figure: A small green pentagon with a dot breaks the rule. B large green triangle with a dot follows the rule. C large red triangle follows the rule. D small blue hexagon follows the rule. So Figure A is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-C'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0004', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Explore', 'easy', 'multiple_choice', 'Four figures: A small red hexagon, B large red pentagon with a dot, C small red hexagon with a dot, D small red triangle. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure B"}, {"id": "B", "text": "Figure D"}, {"id": "C", "text": "Figure C"}, {"id": "D", "text": "Figure A"}]', 'C', 'A figure has a dot exactly when it is large. Check each figure: A small red hexagon follows the rule. B large red pentagon with a dot follows the rule. C small red hexagon with a dot breaks the rule. D small red triangle follows the rule. So Figure C is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-D'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0005', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Explore', 'easy', 'multiple_choice', 'Four figures: A large red pentagon with a dot, B small red triangle with a dot, C small green hexagon, D small blue square with a dot. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure C"}, {"id": "B", "text": "Figure A"}, {"id": "C", "text": "Figure D"}, {"id": "D", "text": "Figure B"}]', 'D', 'A figure is green exactly when it has 3 or 6 sides. Check each figure: A large red pentagon with a dot follows the rule. B small red triangle with a dot breaks the rule. C small green hexagon follows the rule. D small blue square with a dot follows the rule. So Figure B is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-E'], false, 'validated_ha_20260921') on conflict (id) do nothing;
