insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0025', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A large blue triangle, B small green hexagon with a dot, C large red hexagon, D small green triangle. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure A"}, {"id": "B", "text": "Figure D"}, {"id": "C", "text": "Figure B"}, {"id": "D", "text": "Figure C"}]', 'D', 'A figure has a dot exactly when it has an even number of sides. Check each figure: A large blue triangle follows the rule. B small green hexagon with a dot follows the rule. C large red hexagon breaks the rule. D small green triangle follows the rule. So Figure C is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-A'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0026', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A small blue square with a dot, B large red pentagon, C small blue triangle, D large green square with a dot. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure D"}, {"id": "B", "text": "Figure B"}, {"id": "C", "text": "Figure A"}, {"id": "D", "text": "Figure C"}]', 'C', 'A figure is small exactly when it is a triangle. Check each figure: A small blue square with a dot breaks the rule. B large red pentagon follows the rule. C small blue triangle follows the rule. D large green square with a dot follows the rule. So Figure A is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-B'], false, 'validated_ha_20260921') on conflict (id) do nothing;
