insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0047', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A large green hexagon, B small red hexagon with a dot, C small green triangle with a dot, D large red pentagon with a dot. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure A"}, {"id": "B", "text": "Figure B"}, {"id": "C", "text": "Figure C"}, {"id": "D", "text": "Figure D"}]', 'B', 'A figure is green exactly when it has 3 or 6 sides. Check each figure: A large green hexagon follows the rule. B small red hexagon with a dot breaks the rule. C small green triangle with a dot follows the rule. D large red pentagon with a dot follows the rule. So Figure B is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-E'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0048', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A large green square with a dot, B small red hexagon with a dot, C small blue pentagon, D small green triangle. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure B"}, {"id": "B", "text": "Figure C"}, {"id": "C", "text": "Figure A"}, {"id": "D", "text": "Figure D"}]', 'A', 'A figure has a dot exactly when it is large AND has an even number of sides. Check each figure: A large green square with a dot follows the rule. B small red hexagon with a dot breaks the rule. C small blue pentagon follows the rule. D small green triangle follows the rule. So Figure B is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-F'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0049', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A large green pentagon, B small red hexagon with a dot, C small green hexagon, D small green square with a dot. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure B"}, {"id": "B", "text": "Figure D"}, {"id": "C", "text": "Figure C"}, {"id": "D", "text": "Figure A"}]', 'C', 'A figure has a dot exactly when it has an even number of sides. Check each figure: A large green pentagon follows the rule. B small red hexagon with a dot follows the rule. C small green hexagon breaks the rule. D small green square with a dot follows the rule. So Figure C is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-A'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0050', 'pattern_abstract', 'Pattern and Abstract', '5.3', 'figure_odd_one_rule', 'Think', 'medium', 'multiple_choice', 'Four figures: A small red hexagon, B small red triangle, C small blue triangle, D large red square with a dot. Three of them follow the same hidden rule, and one does not. Which figure does NOT belong?', '[{"id": "A", "text": "Figure A"}, {"id": "B", "text": "Figure B"}, {"id": "C", "text": "Figure D"}, {"id": "D", "text": "Figure C"}]', 'A', 'A figure is small exactly when it is a triangle. Check each figure: A small red hexagon breaks the rule. B small red triangle follows the rule. C small blue triangle follows the rule. D large red square with a dot follows the rule. So Figure A is the odd one out.', 'Find the abstract SPONCS rule shared by three figures.', false, NULL, NULL, ARRAY['odd_one_out', 'ODD-B'], false, 'validated_ha_20260921') on conflict (id) do nothing;
