insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0226', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'compound_rule_analogy', 'Think', 'medium', 'multiple_choice', '9 is to 44 as 2 is to ___?', '[{"id": "A", "text": "15"}, {"id": "B", "text": "18"}, {"id": "C", "text": "16"}, {"id": "D", "text": "17"}]', 'C', 'Find the hidden two-step rule: x 4 then + 8. Check: 9 x 4 + 8 = 44. Apply it: 2 x 4 + 8 = 16.', 'Discover a two-step rule and apply it.', false, NULL, NULL, ARRAY['number_analogy', 'dual_rule'], false, 'validated_ha_20260921') on conflict (id) do nothing;
