insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0249', 'numerical_reasoning', 'Numerical Thinking', '1.4', 'chained_comparison', 'Think', 'medium', 'multiple_choice', 'Dan has 3 more stamps than Ben. Ben has 2 fewer stamps than Diya. Diya has 4 fewer stamps than Eli. Diya has 19 stamps. How many stamps does Dan have?', '[{"id": "A", "text": "20"}, {"id": "B", "text": "21"}, {"id": "C", "text": "23"}, {"id": "D", "text": "17"}]', 'A', 'Work along the chain from Diya (19): Dan = 20; Ben = 17; Diya = 19; Eli = 23. So Dan has 20.', 'Chain three comparisons from the known count.', false, NULL, NULL, ARRAY['chain_comparison', 'four_person'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0250', 'numerical_reasoning', 'Numerical Thinking', '1.4', 'chained_comparison', 'Think', 'medium', 'multiple_choice', 'Hana has 3 fewer shells than Iris. Iris has 2 fewer shells than Gina. Gina has 3 fewer shells than Bella. Bella has 21 shells. Who has the most shells?', '[{"id": "A", "text": "Iris"}, {"id": "B", "text": "Gina"}, {"id": "C", "text": "Bella"}, {"id": "D", "text": "Hana"}]', 'C', 'Work along the chain from Bella (21): Hana = 13; Iris = 16; Gina = 18; Bella = 21. The most is Bella.', 'Chain three comparisons from the known count.', false, NULL, NULL, ARRAY['chain_comparison', 'four_person'], false, 'validated_ha_20260921') on conflict (id) do nothing;
