insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0277', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number is a multiple of 4, then it is even. Given: 79 is not even. What MUST be true?', '[{"id": "A", "text": "79 is not a multiple of 4"}, {"id": "B", "text": "All odd numbers end in 9"}, {"id": "C", "text": "79 is a multiple of 4"}, {"id": "D", "text": "79 is even"}]', 'A', 'Multiples of 4 are always even. Since 79 is not even, it cannot be a multiple of 4.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0278', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number ends in 0, then it is a multiple of 5. Given: 37 is not a multiple of 5. What MUST be true?', '[{"id": "A", "text": "37 ends in 0"}, {"id": "B", "text": "37 ends in 5"}, {"id": "C", "text": "37 is a multiple of 5"}, {"id": "D", "text": "37 does not end in 0"}]', 'D', 'Ending in 0 forces a multiple of 5. Since 37 is not a multiple of 5, it cannot end in 0.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0281', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number is a multiple of 4, then it is even. Given: 61 is not even. What MUST be true?', '[{"id": "A", "text": "61 is not a multiple of 4"}, {"id": "B", "text": "61 is even"}, {"id": "C", "text": "61 is a multiple of 4"}, {"id": "D", "text": "All odd numbers end in 1"}]', 'A', 'Multiples of 4 are always even. Since 61 is not even, it cannot be a multiple of 4.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0282', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a card belongs in the blue box, then it has a star. Given: Card 9 has no star. What MUST be true?', '[{"id": "A", "text": "Card 9 does not belong in the blue box"}, {"id": "B", "text": "Card 9 has a star"}, {"id": "C", "text": "the blue box has no cards with stars"}, {"id": "D", "text": "Card 9 belongs in the blue box"}]', 'A', 'The rule says belonging needs a star. Card 9 has no star, so it cannot belong in the blue box.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0283', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number ends in 0, then it is a multiple of 5. Given: 41 is not a multiple of 5. What MUST be true?', '[{"id": "A", "text": "41 ends in 0"}, {"id": "B", "text": "41 ends in 5"}, {"id": "C", "text": "41 is a multiple of 5"}, {"id": "D", "text": "41 does not end in 0"}]', 'D', 'Ending in 0 forces a multiple of 5. Since 41 is not a multiple of 5, it cannot end in 0.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0284', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a card belongs in Box A, then it has a star. Given: Card 9 has no star. What MUST be true?', '[{"id": "A", "text": "Card 9 does not belong in Box A"}, {"id": "B", "text": "Card 9 has a star"}, {"id": "C", "text": "Box A has no cards with stars"}, {"id": "D", "text": "Card 9 belongs in Box A"}]', 'A', 'The rule says belonging needs a star. Card 9 has no star, so it cannot belong in Box A.', 'Use the contrapositive: deny the result, deny the cause.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0285', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Gus saves $10, Gus buys a model kit. If Gus buys a model kit, Gus builds it on Sunday. Today Gus does NOT build it on Sunday. What MUST be true?', '[{"id": "A", "text": "Gus saves $10"}, {"id": "B", "text": "Gus builds it on Sunday"}, {"id": "C", "text": "Gus did NOT save $10"}, {"id": "D", "text": "Gus buys a model kit"}]', 'C', 'Chain the rules backwards: no final step means the middle step did not happen, which means the first step did not happen either. So Gus did NOT save $10.', 'Chain two contrapositives backwards.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0286', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Fiona finishes homework early, Fiona reads a book. If Fiona reads a book, Fiona learns new words. Today Fiona does NOT learn new words. What MUST be true?', '[{"id": "A", "text": "Fiona finishes homework early"}, {"id": "B", "text": "Fiona learns new words"}, {"id": "C", "text": "Fiona reads a book"}, {"id": "D", "text": "Fiona did NOT finish homework early"}]', 'D', 'Chain the rules backwards: no final step means the middle step did not happen, which means the first step did not happen either. So Fiona did NOT finish homework early.', 'Chain two contrapositives backwards.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0287', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Ali hears the bell, Ali lines up. If Ali lines up, Ali walks to class quietly. Today Ali does NOT walk to class quietly. What MUST be true?', '[{"id": "A", "text": "Ali lines up"}, {"id": "B", "text": "Ali did NOT hear the bell"}, {"id": "C", "text": "Ali walks to class quietly"}, {"id": "D", "text": "Ali hears the bell"}]', 'B', 'Chain the rules backwards: no final step means the middle step did not happen, which means the first step did not happen either. So Ali did NOT hear the bell.', 'Chain two contrapositives backwards.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0288', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Iris saves $10, Iris buys a model kit. If Iris buys a model kit, Iris builds it on Sunday. Today Iris does NOT build it on Sunday. What MUST be true?', '[{"id": "A", "text": "Iris buys a model kit"}, {"id": "B", "text": "Iris builds it on Sunday"}, {"id": "C", "text": "Iris did NOT save $10"}, {"id": "D", "text": "Iris saves $10"}]', 'C', 'Chain the rules backwards: no final step means the middle step did not happen, which means the first step did not happen either. So Iris did NOT save $10.', 'Chain two contrapositives backwards.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0289', 'visual_spatial', 'Visual and Spatial', '4.1', 'two_step_rotation', 'Think', 'medium', 'multiple_choice', 'An arrow points UP. It turns 90 degrees clockwise, then it turns 90 degrees clockwise. Which way does it point now?', '[{"id": "A", "text": "LEFT"}, {"id": "B", "text": "DOWN"}, {"id": "C", "text": "UP"}, {"id": "D", "text": "RIGHT"}]', 'B', 'Track it step by step starting from UP. Applying each of the 2 moves in order lands on DOWN.', 'Apply each turn or mirror in order.', false, NULL, NULL, ARRAY['rotation', 'multi_step'], false, 'validated_ha_20260921') on conflict (id) do nothing;
