insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0301', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'interleaved_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 2, 4, 5, 10, 11, 22, 23, ___?', '[{"id": "A", "text": "47"}, {"id": "B", "text": "24"}, {"id": "C", "text": "46"}, {"id": "D", "text": "45"}]', 'C', 'Alternate two steps: times 2, then plus 1. 2 -> 4 -> 5 -> 10 -> 11 -> 22 -> 23: each odd step doubles, each even step adds 1. Next is 23 x 2 = 46.', 'Spot two alternating rules.', false, NULL, NULL, ARRAY['sequence', 'interleaved'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0302', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'alternating_rule', 'Challenge', 'hard', 'multiple_choice', 'Each number is the sum of the two before it: 2, 6, 8, 14, ___, 36, 58. What is the missing number?', '[{"id": "A", "text": "24"}, {"id": "B", "text": "21"}, {"id": "C", "text": "22"}, {"id": "D", "text": "23"}]', 'C', 'Add neighbours: 8 + 14 = 22. Check forward: 14 + 22 = 36.', 'Use the addition rule to fill the gap.', false, NULL, NULL, ARRAY['sequence', 'fibonacci_gap'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0303', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'interleaved_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 3, 8, 6, 11, 9, 14, ___?', '[{"id": "A", "text": "19"}, {"id": "B", "text": "13"}, {"id": "C", "text": "12"}, {"id": "D", "text": "11"}]', 'C', 'The jumps alternate +5 then -2. Last jump was -2, so the next jump is +5: 14 gives 12.', 'Spot the alternating jumps.', false, NULL, NULL, ARRAY['sequence', 'alternating_jumps'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0304', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'interleaved_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 2, 4, 5, 10, 11, 22, 23, ___?', '[{"id": "A", "text": "46"}, {"id": "B", "text": "47"}, {"id": "C", "text": "45"}, {"id": "D", "text": "24"}]', 'A', 'Alternate two steps: times 2, then plus 1. 2 -> 4 -> 5 -> 10 -> 11 -> 22 -> 23: each odd step doubles, each even step adds 1. Next is 23 x 2 = 46.', 'Spot two alternating rules.', false, NULL, NULL, ARRAY['sequence', 'interleaved'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0305', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'alternating_rule', 'Challenge', 'hard', 'multiple_choice', 'Each number is the sum of the two before it: 4, 6, 10, 16, ___, 42, 68. What is the missing number?', '[{"id": "A", "text": "25"}, {"id": "B", "text": "27"}, {"id": "C", "text": "26"}, {"id": "D", "text": "28"}]', 'C', 'Add neighbours: 10 + 16 = 26. Check forward: 16 + 26 = 42.', 'Use the addition rule to fill the gap.', false, NULL, NULL, ARRAY['sequence', 'fibonacci_gap'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0306', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'interleaved_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 6, 9, 8, 11, 10, 13, ___?', '[{"id": "A", "text": "11"}, {"id": "B", "text": "13"}, {"id": "C", "text": "12"}, {"id": "D", "text": "16"}]', 'C', 'The jumps alternate +3 then -1. Last jump was -1, so the next jump is +3: 13 gives 12.', 'Spot the alternating jumps.', false, NULL, NULL, ARRAY['sequence', 'alternating_jumps'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0307', 'problem_solving', 'Problem Solving', '6.3', 'before_after', 'Think', 'medium', 'multiple_choice', 'Eva has 10 more cards than Amy. Eva gives Amy 2 cards. Now who has more cards, and by how many?', '[{"id": "A", "text": "Tied"}, {"id": "B", "text": "Amy by 6"}, {"id": "C", "text": "Eva by 10"}, {"id": "D", "text": "Eva by 6"}]', 'D', 'Start: Eva leads by 10. The gift moves 2 each way, closing the gap by 4. New gap is 6 to Eva.', 'One gift closes the gap twice over.', false, NULL, NULL, ARRAY['before_after', 'gap_closes_double'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0308', 'problem_solving', 'Problem Solving', '6.3', 'before_after', 'Think', 'medium', 'multiple_choice', 'Cai has 5 more stickers than Iris. Cai gives Iris 7 stickers. Now who has more stickers, and by how many?', '[{"id": "A", "text": "Iris by 5"}, {"id": "B", "text": "Cai by 9"}, {"id": "C", "text": "Tied"}, {"id": "D", "text": "Iris by 9"}]', 'D', 'Start: Cai leads by 5. The gift moves 7 each way, closing the gap by 14. New gap is 9 to Iris.', 'One gift closes the gap twice over.', false, NULL, NULL, ARRAY['before_after', 'gap_closes_double'], false, 'validated_ha_20260921') on conflict (id) do nothing;
