insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0313', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Think', 'medium', 'multiple_choice', 'A number is multiplied by 3, then 10 is added, and the result is 46. What was the starting number?', '[{"id": "A", "text": "12"}, {"id": "B", "text": "11"}, {"id": "C", "text": "14"}, {"id": "D", "text": "13"}]', 'A', 'Undo backwards: subtract first (46 - 10 = 36), then divide (36 / 3 = 12). Check forward: 12 x 3 + 10 = 46.', 'Undo each step in reverse.', false, NULL, NULL, ARRAY['working_backwards', 'two_step'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0314', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A triangle and a oval together weigh 19. A triangle and a pentagon together weigh 21. A pentagon and a oval together weigh 18. Which shape is the heaviest?', '[{"id": "A", "text": "triangle"}, {"id": "B", "text": "All weigh the same"}, {"id": "C", "text": "oval"}, {"id": "D", "text": "pentagon"}]', 'A', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 29. Then triangle = 11, pentagon = 10, oval = 8. The heaviest is the triangle.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0315', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A oval and a triangle together weigh 16. A hexagon and a oval together weigh 17. A hexagon and a triangle together weigh 19. How much does one hexagon weigh?', '[{"id": "A", "text": "7"}, {"id": "B", "text": "10"}, {"id": "C", "text": "9"}, {"id": "D", "text": "11"}]', 'B', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 26. The other two shapes weigh 16, so one hexagon weighs 26 - 16 = 10.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
