insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0352', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a card belongs in the red tray, then it has a star. Given: Card 17 has no star. What MUST be true?', '[{"id": "A", "text": "Card 17 belongs in the red tray"}, {"id": "B", "text": "Card 17 does not belong in the red tray"}, {"id": "C", "text": "Card 17 has a star"}, {"id": "D", "text": "the red tray throws away all its stars"}]', 'B', 'Deny the result, deny the cause. Card 17 has no star. So card 17 does not belong in the red tray.', 'Use the contrapositive.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0353', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number is a multiple of 10, then it is even. Given: 27 is not even. What MUST be true?', '[{"id": "A", "text": "27 is not a multiple of 10"}, {"id": "B", "text": "27 is half of 10"}, {"id": "C", "text": "27 is even"}, {"id": "D", "text": "27 is a multiple of 10"}]', 'A', 'Deny the result, deny the cause. 27 is not even. So 27 is not a multiple of 10.', 'Use the contrapositive.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
