insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0360', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number is a multiple of 4, then it is even. Given: 33 is not even. What MUST be true?', '[{"id": "A", "text": "33 is not a multiple of 4"}, {"id": "B", "text": "33 is a multiple of 4"}, {"id": "C", "text": "33 is half of 4"}, {"id": "D", "text": "33 is even"}]', 'A', 'Deny the result, deny the cause. 33 is not even. So 33 is not a multiple of 4.', 'Use the contrapositive.', false, NULL, NULL, ARRAY['logic', 'contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0361', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Finn finishes homework early, Finn reads a book. If Finn reads a book, Finn learns new words. Today Finn does NOT learn new words. What MUST be true?', '[{"id": "A", "text": "Finn did NOT finish homework early"}, {"id": "B", "text": "Finn learns new words"}, {"id": "C", "text": "Finn finishes homework early"}, {"id": "D", "text": "Finn reads a book"}]', 'A', 'Chain backwards: no final step means the middle step did not happen, so the first step did not happen. Finn did NOT finish homework early.', 'Chain two contrapositives.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0362', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Diya finishes homework early, Diya reads a book. If Diya reads a book, Diya learns new words. Today Diya does NOT learn new words. What MUST be true?', '[{"id": "A", "text": "Diya learns new words"}, {"id": "B", "text": "Diya did NOT finish homework early"}, {"id": "C", "text": "Diya reads a book"}, {"id": "D", "text": "Diya finishes homework early"}]', 'B', 'Chain backwards: no final step means the middle step did not happen, so the first step did not happen. Diya did NOT finish homework early.', 'Chain two contrapositives.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0363', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Ali finishes homework early, Ali reads a book. If Ali reads a book, Ali learns new words. Today Ali does NOT learn new words. What MUST be true?', '[{"id": "A", "text": "Ali did NOT finish homework early"}, {"id": "B", "text": "Ali reads a book"}, {"id": "C", "text": "Ali learns new words"}, {"id": "D", "text": "Ali finishes homework early"}]', 'A', 'Chain backwards: no final step means the middle step did not happen, so the first step did not happen. Ali did NOT finish homework early.', 'Chain two contrapositives.', false, NULL, NULL, ARRAY['logic', 'chained_contrapositive'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0364', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Ali saves $10, Ali buys a model kit. If Ali buys a model kit, Ali builds it on Sunday. Today Ali saves $10. What MUST be true?', '[{"id": "A", "text": "Ali does NOT build it on Sunday"}, {"id": "B", "text": "Ali does NOT buy a model kit"}, {"id": "C", "text": "Ali does NOT save $10"}, {"id": "D", "text": "Ali builds it on Sunday"}]', 'D', 'Chain forwards: the first step happened, so the middle step happened, so the final step happened. Ali builds it on Sunday.', 'Chain two rules forwards.', false, NULL, NULL, ARRAY['logic', 'chained_affirm'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0365', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Finn finishes homework early, Finn reads a book. If Finn reads a book, Finn learns new words. Today Finn finishes homework early. What MUST be true?', '[{"id": "A", "text": "Finn does NOT read a book"}, {"id": "B", "text": "Finn does NOT learn new words"}, {"id": "C", "text": "Finn learns new words"}, {"id": "D", "text": "Finn does NOT finish homework early"}]', 'C', 'Chain forwards: the first step happened, so the middle step happened, so the final step happened. Finn learns new words.', 'Chain two rules forwards.', false, NULL, NULL, ARRAY['logic', 'chained_affirm'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0366', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Cai hears the bell, Cai lines up. If Cai lines up, Cai walks to class quietly. Today Cai hears the bell. What MUST be true?', '[{"id": "A", "text": "Cai does NOT walk to class quietly"}, {"id": "B", "text": "Cai walks to class quietly"}, {"id": "C", "text": "Cai does NOT line up"}, {"id": "D", "text": "Cai does NOT hear the bell"}]', 'B', 'Chain forwards: the first step happened, so the middle step happened, so the final step happened. Cai walks to class quietly.', 'Chain two rules forwards.', false, NULL, NULL, ARRAY['logic', 'chained_affirm'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0367', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A circle and a diamond together weigh 6. A diamond and a oval together weigh 7. A circle and a oval together weigh 5. Which shape is the heaviest?', '[{"id": "A", "text": "All weigh the same"}, {"id": "B", "text": "diamond"}, {"id": "C", "text": "oval"}, {"id": "D", "text": "circle"}]', 'B', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 9. Then circle = 2, diamond = 4, oval = 3. The heaviest is the diamond.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0368', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A square and a star together weigh 13. A pentagon and a star together weigh 16. A square and a pentagon together weigh 17. How much does one square weigh?', '[{"id": "A", "text": "6"}, {"id": "B", "text": "8"}, {"id": "C", "text": "7"}, {"id": "D", "text": "10"}]', 'C', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 23. The other two shapes weigh 16, so one square weighs 23 - 16 = 7.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0369', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A circle and a triangle together weigh 19. A triangle and a hexagon together weigh 17. A circle and a hexagon together weigh 14. Which shape is the heaviest?', '[{"id": "A", "text": "triangle"}, {"id": "B", "text": "circle"}, {"id": "C", "text": "All weigh the same"}, {"id": "D", "text": "hexagon"}]', 'A', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 25. Then circle = 8, triangle = 11, hexagon = 6. The heaviest is the triangle.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0370', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A square and a circle together weigh 12. A circle and a oval together weigh 16. A square and a oval together weigh 10. How much does one circle weigh?', '[{"id": "A", "text": "10"}, {"id": "B", "text": "3"}, {"id": "C", "text": "8"}, {"id": "D", "text": "9"}]', 'D', 'Add all three pair-weights: each shape is counted twice, so one of each weighs 19. The other two shapes weigh 10, so one circle weighs 19 - 10 = 9.', 'Solve a 3-variable balance system by summing pairs.', false, NULL, NULL, ARRAY['weight_system', 'balance'], false, 'validated_ha_20260921') on conflict (id) do nothing;
insert into public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, visual_required, visual_spec, image_path, tags, is_active, qa_status) values ('BA_P3_HA_0371', 'pattern_abstract', 'Pattern and Abstract', '5.1', 'figure_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 2, 4, 5, 10, 11, 22, 23, ___?', '[{"id": "A", "text": "24"}, {"id": "B", "text": "46"}, {"id": "C", "text": "45"}, {"id": "D", "text": "47"}]', 'B', 'Alternate two steps: times 2, then plus 1. Next is 23 x 2 = 46.', 'Spot two alternating rules.', false, NULL, NULL, ARRAY['sequence', 'interleaved'], false, 'validated_ha_20260921') on conflict (id) do nothing;
